CREATE TABLE woe_matches (match_id TEXT PRIMARY KEY, room_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, state_json TEXT NOT NULL, event_seq INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, finished_at INTEGER);
CREATE INDEX woe_matches_running ON woe_matches(status,match_id);
CREATE TABLE woe_match_participants (match_id TEXT NOT NULL REFERENCES woe_matches(match_id) ON DELETE CASCADE, controller_id TEXT NOT NULL, team TEXT NOT NULL, human INTEGER NOT NULL, forfeited INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(match_id,controller_id));
CREATE INDEX woe_participants_player ON woe_match_participants(controller_id,human,match_id);
CREATE TABLE woe_match_events (match_id TEXT NOT NULL REFERENCES woe_matches(match_id) ON DELETE CASCADE, seq INTEGER NOT NULL, event_json TEXT NOT NULL, PRIMARY KEY(match_id,seq));
CREATE TABLE woe_match_actions (match_id TEXT NOT NULL REFERENCES woe_matches(match_id) ON DELETE CASCADE, player_id TEXT NOT NULL, action_id TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, status INTEGER NOT NULL, response TEXT NOT NULL, PRIMARY KEY(match_id,player_id,action_id));
INSERT INTO woe_matches(match_id,room_id,status,state_json,created_at,updated_at) SELECT match_id,room_id,'RUNNING',match_json,created_at,updated_at FROM woe_rooms WHERE status='STARTED' AND match_id IS NOT NULL AND match_json IS NOT NULL;
INSERT INTO woe_match_participants(match_id,controller_id,team,human) SELECT r.match_id,json_extract(j.value,'$.controller_id'),CASE WHEN json_extract(j.value,'$.seat') LIKE 'blue%' THEN 'blue' ELSE 'red' END,CASE WHEN json_extract(j.value,'$.bot') THEN 0 ELSE 1 END FROM woe_rooms r,json_each(r.mapping_json) j WHERE r.match_id IN (SELECT match_id FROM woe_matches);
